---@param data table @ 当前食物
function MaidCoffeeUtils.CalculationCanMakeFoodCount(data)
    local canMakeNum = nil
    for i = 1, 3 do
        if i <= #data.foodStuff then
            local needId = tonumber(data.foodStuff[i])
            local needNum = tonumber(data.foodStuffNum[i])
            local haveNum = GoodsUtils.GetThingNo(needId)
            ---计算一下最大能做多少个
            local makeNum = math.floor(haveNum / needNum)
            if makeNum == 0 then
                return 0
            else
                if not isNull(canMakeNum) then
                    if makeNum < canMakeNum then
                        canMakeNum = makeNum
                    end
                else
                    canMakeNum = makeNum
                end
            end
        end
    end

    return canMakeNum or 0
end

---FillCoffeeSkillDescription
---@param description string
---@param additionNum number[]
---@param extraNum table
function MaidCoffeeUtils.FillCoffeeSkillDescription(description, additionNum, extraNum, percentage)
    ---根据规则优先处理_target_id_
    local time = 1
    ---@type GoodsConfMgr
    local goodsConfMgr = GoodsConfMgr:GetInstance()
    for m in string.gmatch(description, "_target_id_") do
        local v = ''
        if additionNum[time] then
            ---存在数据
            local vo = goodsConfMgr:GetGoodsVoById(checkNumber(additionNum[time]))
            if vo then
                v = vo.name
            end
        end
        description = string.gsub(description, m, v, 1)
        time = time + 1
    end

    for m in string.gmatch(description, "_target_num_") do
        local v = ''
        local extra = 0
        if extraNum then
            ---存在要合并的数据
            for i, extraT in pairs(extraNum) do
                local additionNum = extraT.additionNum
                if additionNum[time] then
                    ---存在数据
                    extra = extra + checkNumber(additionNum[time])
                end
            end
        end
        if additionNum[time] then
            ---存在数据 当第一位为1的时候  认为是百分之百
            if tonumber(percentage[time]) == 1 then
                v = attribute_format(1, additionNum[time] + extra) .. '%'
            else
                v = tostring(additionNum[time] + extra)
            end
        end
        description = string.gsub(description, m, v, 1)
        time = time + 1
    end
    return description
end

function MaidCoffeeUtils.GetCardMoodStatus(point)
    local status = 3
    local max = MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(5)
    local min = MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(6)
    if point <= tonumber(min.num) then
        status = 1
    elseif point > tonumber(min.num) and point <= tonumber(max.num) then
        status = 2
    else
        status = 3
    end
    return status
end

function MaidCoffeeUtils.FillSoulImage(node, point)
    local status = MaidCoffeeUtils.GetCardMoodStatus(point)
    CfUtils.SetUISwitchImage(node,status)
end

local function GetIdGroupData(idSetting, key, throwError, suffix)
    local tableName = string.format("%s%s", idSetting, string.isEmpty(suffix) and "IDGroup" or suffix)
    local tableFile = SettingMgr:GetInstance():Get(tableName)
    ---@type TableML.TableFileRow
    local row = tableFile:GetByPrimaryKey(checkString(key), throwError)
    return row
end

local function GetIdGroupRowData(idSetting, key, rowName, throwError, splitFlag)
    rowName = rowName or "ids"
    ---@type TableML.TableFileRow
    local row = GetIdGroupData(idSetting, key, throwError)
    if not isNull(row) then
        local ids = checkTable(parse_strings(row:Get(rowName), splitFlag or ';'))
        return ids
    end
    return nil
end

