--- EnterMaidCoffeePopUp
function MaidCoffeeUtils.EnterMaidCoffeePopUp()
    cs_coroutine.start(function()
        local key = "MaidCoffee_IsPopPcTips"
        local isPopUpPcTip = checkNumber(CfUtils.GetLocalData(key))
        if GameUtils.IsPCPlatform() then
            ---为1 说明打开过了  直接弹出来打脸的报表界面
            if isPopUpPcTip ~= 1 then
                coroutine.yield(CS.Engine.Lib.Yielders.GetWaitForSeconds(checkNumber(0.5)))
                MaidCoffeeUtils.EnterPCTipsDialog(key)
            end
        end
    end)
end

function MaidCoffeeUtils.GetCurMoodByCardFavorabilityLevel(cardId, favorabilityLevel)
    local ids = GetIdGroupRowData(AutoIds.IdSetting58, cardId, "ids", false, ";")
    if ids == nil then
        printError("卡牌id %s 未在 好感度经验奖励表 找到对应数据", cardId)
        return 0
    end

    local _vo
    for i, id in pairs(ids) do
        ---@type FavorableExpRewardVo
        local vo = CfUtils.GetCfVo(AutoIds.IdSetting58, "FavorableExpRewardVo", id)
        if vo == nil then
            printError("id %s 未在 好感度经验奖励表 找到对应数据", id)
        end
        if favorabilityLevel >= vo.level then
            _vo = vo
        end
    end
    return (_vo ~= nil) and _vo.mood or 0
end

