function MaidCoffeeUtils.CheckIsCanLoungeSelectCard(cardDojo, limitType, limitStatus2Status)
    local cafeEnergy = checkNumber(cardDojo.cafeEnergy)
    local maxEnergy  = CardConfMgr:GetInstance():GetCardMoodByCardIdLevel(cardDojo.cardId, cardDojo.favorabilityLevel)
    local cafeStatus = checkNumber(cardDojo.cafeStatus)
    ---心情值不满 或者 卡牌状态是 在休息室中
    return (not limitStatus2Status[cafeStatus] and cafeEnergy < maxEnergy) or cafeStatus == limitType
end
---CalcCatRollEnergyLimit
---@param catId number 猫球id
---@param level number 猫球等级
function MaidCoffeeUtils.CalcCatRollEnergyLimit(catId, level)
    ---@type MaidCoffeeCatRollConfigVo
    local configVo = MaidCoffeeUtils.GetMaidCoffeeCatRollConfigVo(catId)
    local energy   = configVo.energy + MaidCoffeeUtils.CalcCatRollAdditionEnergy(level)
    return energy
end
function MaidCoffeeUtils.CalcCatRollAdditionEnergy(level)
    local energy = 0
    for i = 1, level do
        ---@type MaidCoffeeCatRollLevelVo
        local levelVo = MaidCoffeeUtils.GetMaidCoffeeCatRollLevelVo(i)
        if levelVo then
            energy = energy + levelVo.energyNum
        else
            printError("猫球等级表 未找到等级 %s", i)
        end
    end
    return energy
end

---CalcMaxBackpackCapacity
function MaidCoffeeUtils.CalcMaxBackpackCapacity()
    ---@type CatEggComponent
    local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
    local extendTimes  = eggComponent:GetExtendTimes()
    --eggComponent:Get
    local capacity = checkNumber(MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(MaidCoffeeConstants.ParamsIds.CatBallStoneInitCapacity).num)
    ---@type MaidCoffeeCatRollStoreVo
    local vo
    for times = 1, extendTimes do
        vo = MaidCoffeeUtils.GetMaidCoffeeCatRollStoreVo(times)
        capacity = capacity + vo.placeNum
    end
    return capacity
end

---CalcMaxBackpackCapacity
function MaidCoffeeUtils.CalcMaxBackpackExtendTimes()
    local times = 0
    ---@type MaidCoffeeCatRollStoreVo[]
    local vos = CfUtils.GetCf(AutoIds.IdSetting4004, "MaidCoffeeCatRollStoreVo", true)
    for i, v in ipairs(vos) do
        times = math.max(times, v.id)
    end
    return times
end

---CalcCurrentBackpackSize
---计算当前背包的大小
function MaidCoffeeUtils.CalcCurrentBackpackSize()
    ---非主题猫 加 大类4的道具
    ---@type CatEggComponent
    local eggComponent     = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
    local playerCatId2Dojo = eggComponent:GetCats()
    local size             = 0
    ---@param dojo CatEggDojo
    for i, dojo in pairs(playerCatId2Dojo) do
        ---@type MaidCoffeeCatRollConfigVo
        local vo = MaidCoffeeUtils.GetMaidCoffeeCatRollConfigVo(dojo.catId)
        if vo.quality ~= MaidCoffeeConstants.CatBallQuality.Theme then
            size = size + 1
        end
    end
    local checkNumber = checkNumber
    local convertBackpack = eggComponent:GetConvertBackpack()
    for i, v in pairs(convertBackpack) do
        if checkNumber(v) > 0 then
            size = size + 1
        end
    end

    return size
end


--- 猫球vo是否为主题猫
---@param catRollVo MaidCoffeeCatRollConfigVo
function MaidCoffeeUtils.CheckCatRollIsTheme(catRollVo)
    return catRollVo and catRollVo.quality == MaidCoffeeConstants.CatBallQuality.Theme
end

---CalcCatRollMaxStar
function MaidCoffeeUtils.CalcCatRollMaxStar()
    ---@type MaidCoffeeCatRollStarVo[]
    local vos = CfUtils.GetCf(AutoIds.IdSetting4002, "MaidCoffeeCatRollStarVo", true)
    local maxStar = 0
    for i, vo in ipairs(vos) do
        maxStar = math.max(maxStar, vo.starId)
    end
    return maxStar
end


---IsCatPacketIsFull
---是否猫球背包已满的判断，不能进行抽猫球等操作
function MaidCoffeeUtils.IsCatPacketIsFull()
    local capacity      = MaidCoffeeUtils.CalcMaxBackpackCapacity()
    local pro = MaidCoffeeUtils.CalcCurrentBackpackSize()
    return pro >= capacity
end


function MaidCoffeeUtils.GetAssetByLoader(loader)
    if isNull(loader) then
        return
    end

    while not loader.IsCompleted do
        yield_return()
    end

    local ret = nil
    if loader.IsSuccess then
        ret = loader.ResultObject
    end
    loader:Release()
    return ret
end

function MaidCoffeeUtils.SetRoleDitherIntensity(isShow,node)
    local _skinnedMeshes
    if not isNull(node) then
        _skinnedMeshes = node:GetComponentsInChildren(typeof(SkinnedMeshRenderer))
    end

    if not isNull(_skinnedMeshes) then
        for i = 1, _skinnedMeshes.Length do
            local skinned = _skinnedMeshes[i - 1]
            local materials = skinned.materials
            for i = 1, materials.Length do
                local material = materials[i -1]
                CfUtils.DoTween(1,function(_value)
                    local value = _value
                    if not isShow then
                        value = 1 - _value
                    end
                    material:SetFloat("_DitherIntensity", value)
                end)
            end
        end
    end
end

function MaidCoffeeUtils.UpdateCoffeeExp(data)
    if isNull(data) then return end
    if data.goodsId ~= Constants.CoffeeShowItem.PraisePointId then return end
    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(data.goodsId)
    if goodsVo then
        local addNum = data.num
        ---@type MaidCoffeePlayerComponent
        local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
        if component then
            component:UpdateCafeExp(addNum)
        end
    end
end

function MaidCoffeeUtils.FillWorkImgStatus(txt,img,status,isShowFree)
    local state = 0
    if status == MaidCoffeeConstants.CafeStatus.Non then
        if isShowFree then
            state = 4
        end
    elseif status == MaidCoffeeConstants.CafeStatus.UnderManagement or status == MaidCoffeeConstants.CafeStatus.InService then
        state = 2
    elseif status == MaidCoffeeConstants.CafeStatus.InTakeaway then
        state = 1
    elseif status == MaidCoffeeConstants.CafeStatus.Resting then
        state = 3
    end
    if state ~= 0 then
        CfUtils.SetUISwitchText(txt,state)
        CfUtils.SetUISwitchImage(img,state)
    end
end

