function MaidCoffeeUtils.GetSuitAestheticsValue(furnitureIds)
    local value = 0
    for i, v in pairs(furnitureIds) do
        local vo = MaidCoffeeUtils.GetRenovateInfoVo(v)
        if not isNull(vo) then
            value = value + vo.decorationValue
        end
    end
    return value
end

