function MaidCoffeeUtils.MaidCoffeeVisit(friendId)
    if friendId == 0 then
        local timesVo = CfUtils.GetCfVo(AutoIds.IdSetting3033, "MaidCoffeeManagerSettingVo", 56)
        local totalTimes = checkNumber(timesVo.num)
        local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
        local maidCoffeeHomeDojo = maidCoffeeComponent:GetMaidCoffeeHomeDoJo()
        local haveCallOnTimes = maidCoffeeHomeDojo:GetRandomVisitedTimes()
        if haveCallOnTimes >= totalTimes then
            GameUtils.Toast(localize("随机拜访次数已达上限"))
            return
        end
    end
    GameUtils.Request(Interfaces.OverseaCafeVisit,{friendId = friendId},function(request,response)
        if checkNumber(response.errCode) == 0 then
            local responseData = response.data
            GameUtils.ShowBlackOverlay(nil, function()
                local lastDialog = CS.Engine.UI.UIModule.CurrentScreen:LastDialog()
                if lastDialog.Argument.id == Constants.UITypeIds.OverseaManageOthersMainDialog  then
                    lastDialog.Argument.parameters.data = responseData
                    cs_coroutine.yield_return(lastDialog.Env:RefreshShow(responseData))
                else
                    cs_coroutine.yield_return(CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.OverseaManageOthersMainDialog, parameters = { data = responseData } },
                            {{ id = Constants.UITypeIds.OverseaManageMerchantFriendDialog}}))
                end
            end)
        end
    end)
end

function MaidCoffeeUtils.OpenBusinessStory()
    local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local maidCoffeeHomeDojo = maidCoffeeComponent:GetMaidCoffeeHomeDoJo()
    local data = maidCoffeeHomeDojo:GetMerchantData()
    local key = "OverseaManageBusinessNodeChapter_"..data.merchant.type
    local value = CfUtils.GetLocalData(key)
    local isFirst = checkNumber(value) == 0
    local storyId = isFirst and data.merchant.storyFirstId or data.merchant.storyStartId
    data.storyId = storyId
    UIModule.OpenDialog({ id = Constants.UITypeIds.OverseaManageMerchantTalkingNode, parameters = { data = data} },{
        {id = Constants.UITypeIds.UIMaidCoffeeMainDialog},
        {id = Constants.UITypeIds.OverseaManageOthersMainDialog},
    })
end


