function MaidCoffeeUtils.TestAutoJumpCafe()
    local row = GoodsConfMgr:GetInstance():GetJumpModuleRow(520)
    local t = {}
    local dialogs = UIModule.CurrentScreen.dialogs
    for _, dialog in pairs(dialogs) do
        if checkNumber(dialog.Argument.id) ~= Constants.UITypeIds.UICommonBuyItemDialog then
            table.insert(t, dialog.Argument)
        end
    end

    local autoData = { row = row}
    CfUtils.CookieSave("CafeIsAutoOpen", 1)
    UIModule.OpenDialog({ id = Constants.UITypeIds.UIMaidCoffeeManagerDialog, parameters = { autoData = autoData } }, t, true)
end
